/// The starting set for one campaign and profession, or an empty slice if the reference has
/// none for that pair.
pub fn default_equipment(campaign: u8, profession: u8) -> &'static [ItemSpec] {
    let mut index = 0;
    while index < EQUIPMENT.len() {
        let (entry_campaign, entry_profession, items) = &EQUIPMENT[index];
        if *entry_campaign == campaign && *entry_profession == profession {
            return items;
        }
        index += 1;
    }
    &[]
}
